import clsx from 'clsx';
import React, { useEffect, useRef, useState } from 'react';

interface AnnotationToolButtonProps {
  showTooltip: boolean;
  tooltipText: string;
  disabled?: boolean;
  Icon: React.ElementType;
  onClick: () => void;
  onLongPress?: () => void;
}

const AnnotationToolButton: React.FC<AnnotationToolButtonProps> = ({
  showTooltip,
  tooltipText,
  disabled,
  Icon,
  onClick,
  onLongPress,
}) => {
  const buttonRef = useRef<HTMLButtonElement>(null);
  useEffect(() => {
    const button = buttonRef.current;
    if (!button || !onLongPress) return;
    const preserve = (event: TouchEvent) => {
      event.preventDefault();
      event.stopPropagation();
    };
    button.addEventListener('touchstart', preserve, { passive: false });
    return () => button.removeEventListener('touchstart', preserve);
  }, [onLongPress]);
  const [buttonClicked, setButtonClicked] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const held = useRef(false);
  const start = useRef({ x: 0, y: 0 });
  const cancel = () => {
    if (timer.current !== null) clearTimeout(timer.current);
    timer.current = null;
  };
  useEffect(() => cancel, []);
  return (
    <div
      className='lg:tooltip lg:tooltip-bottom'
      title={!buttonClicked && showTooltip ? tooltipText : undefined}
    >
      <button
        ref={buttonRef}
        onPointerDown={(event) => {
          held.current = false;
          cancel();
          if (disabled || !onLongPress) return;
          event.preventDefault();
          start.current = { x: event.clientX, y: event.clientY };
          timer.current = setTimeout(() => {
            held.current = true;
            onLongPress();
          }, 500);
        }}
        onPointerMove={(event) => {
          if (Math.hypot(event.clientX - start.current.x, event.clientY - start.current.y) > 10)
            cancel();
        }}
        onPointerUp={() => {
          cancel();
          if (onLongPress && !held.current) {
            held.current = true;
            setButtonClicked(true);
            onClick();
          }
        }}
        onPointerCancel={cancel}
        onPointerLeave={cancel}
        onContextMenu={(event) => {
          if (onLongPress) {
            event.preventDefault();
            cancel();
            if (!held.current) onLongPress();
            held.current = true;
          }
        }}
        onClick={() => {
          cancel();
          setButtonClicked(true);
          if (held.current) {
            held.current = false;
            return;
          }
          onClick();
        }}
        aria-label={tooltipText}
        className={clsx(
          'flex h-8 min-h-8 w-8 items-center justify-center p-0',
          disabled
            ? 'cursor-not-allowed opacity-50'
            : 'not-eink:hover:bg-base-200 eink:hover:border rounded-md',
        )}
        style={onLongPress ? { touchAction: 'none', userSelect: 'none' } : undefined}
        disabled={disabled}
      >
        <Icon />
      </button>
    </div>
  );
};
export default AnnotationToolButton;

